[Approach 2] Using  Topological Sorting - O(V + E) Time and O(V) SpaceThe idea is to use Kahn’s algorithm because it works only for Directed Acyclic Graphs (DAGs). So, while performing topological sorting using Kahn’s algorithm, if we are able to include all the vertices in the topological order, it means the graph has no cycle and is a DAG.However, if at the end there are still some vertices left (i.e., their in-degree never becomes 0), it means those vertices are part of a cycle. Hence, if we cannot get all the vertices in the topological sort, the graph must contain at least one cycle.
            C++

    //Driver Code Starts
#include <iostream>
#include<vector>
#include<queue>
using namespace std;

//Driver Code Ends

bool isCyclic(vector<vector<int>> &adj)
{
    int V = adj.size();
    // Array to store in-degree of each vertex
    vector<int> inDegree(V, 0); 
    queue<int> q; 
    // Count of visited (processed) nodes
    int visited = 0;           

    //Compute in-degrees of all vertices
    for (int u = 0; u < V; ++u)
    {
        for (int v : adj[u])
        {
            inDegree[v]++;
        }
    }

    //  Add all vertices with in-degree 0 to the queue
    for (int u = 0; u < V; ++u)
    {
        if (inDegree[u] == 0)
        {
            q.push(u);
        }
    }

    // Perform BFS (Topological Sort)
    while (!q.empty())
    {
        int u = q.front();
        q.pop();
        visited++;

        // Reduce in-degree of neighbors
        for (int v : adj[u])
        {
            inDegree[v]--;
            if (inDegree[v] == 0)
            {
                // Add to queue when in-degree becomes 0
                q.push(v);
            }
        }
    }

    //  If visited nodes != total nodes, a cycle exists
    return visited != V;
}

//Driver Code Starts

int main()
{

    vector<vector<int>> adj = {{1},{2},{0, 3}};

    cout << (isCyclic(adj) ? "true" : "false") << endl;

    return 0;
}
